// Prints the jsCode for the n8n Code node "Validate Order" in Create Order Tool (KrSn4DNR9ALX5ng4).
// Usage: node sales/n8n/build-validate-order.mjs > /tmp/validate-order.js
// The functions are copied from sales/lib/order-rules.mjs so the node and the tests can never drift.
import { HOLD_HOURS, toVnd, normPhone, reservedQty, validateOrder } from '../lib/order-rules.mjs';

export function buildValidateOrderCode() {
  return [
    '// GENERATED by sales/n8n/build-validate-order.mjs from sales/lib/order-rules.mjs. Do not edit in n8n.',
    '// TIEN404 Sale GD1: af9ee686 rules + stock reservation (pending 24h, confirmed/paid 7 days).',
    'const HOLD_HOURS = ' + JSON.stringify(HOLD_HOURS) + ';',
    toVnd.toString(),
    normPhone.toString(),
    reservedQty.toString(),
    validateOrder.toString(),
    "let runKey = '';",
    "try { runKey = String($execution.id ?? ''); } catch (e) {}",
    'const result = validateOrder({',
    "  input: $('Order Input').first().json,",
    "  products: $('Read Products').all().map(i => i.json),",
    "  orders: $('Read Orders').all().map(i => i.json),",
    '  nowMs: Date.now(), runKey, rand: Math.random, holdHours: HOLD_HOURS,',
    '});',
    'return [{ json: result }];',
    '',
  ].join('\n');
}

if (import.meta.url === `file://${process.argv[1]}`) process.stdout.write(buildValidateOrderCode());
